previewCss:
.darma-loader-yin-yang-spin {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 25%, var(--loader-secondary-color, #e0e7ff) 4%, transparent 5%),
    radial-gradient(circle at 50% 75%, var(--loader-color, #6366f1) 4%, transparent 5%),
    radial-gradient(circle at 50% 25%, var(--loader-color, #6366f1) 22%, transparent 23%),
    radial-gradient(circle at 50% 75%, var(--loader-secondary-color, #e0e7ff) 22%, transparent 23%),
    linear-gradient(to right, var(--loader-secondary-color, #e0e7ff) 50%, var(--loader-color, #6366f1) 50%);
  animation: darma-loader-yin-yang-spin-spin 1.4s linear infinite;
}
@keyframes darma-loader-yin-yang-spin-spin { to { transform: rotate(360deg); } }

